func NewMock() (*PrismaClient, *Mock, func(t *testing.T)) {
	expectations := new([]mock.Expectation)
	pc := newMockClient(expectations)
	m := &Mock{
		Mock: &mock.Mock{
			Expectations: expectations,
		},
	}

	m.Organization = organizationMock{
		mock: m,
	}

	m.User = userMock{
		mock: m,
	}

	m.Session = sessionMock{
		mock: m,
	}

	m.Registration = registrationMock{
		mock: m,
	}

	m.Role = roleMock{
		mock: m,
	}

	m.Permission = permissionMock{
		mock: m,
	}

	m.RolePermission = rolePermissionMock{
		mock: m,
	}

	m.UserRole = userRoleMock{
		mock: m,
	}

	m.Component = componentMock{
		mock: m,
	}

	m.ComponentTag = componentTagMock{
		mock: m,
	}

	m.Tag = tagMock{
		mock: m,
	}

	m.Document = documentMock{
		mock: m,
	}

	m.DocumentBlock = documentBlockMock{
		mock: m,
	}

	m.Block = blockMock{
		mock: m,
	}

	m.Change = changeMock{
		mock: m,
	}

	return pc, m, m.Ensure
}

